import type { ReactNode } from "react";

type PanelProps = {
  title: string;
  children: ReactNode;
  onClose?: () => void;
};

export function Panel({ title, children, onClose }: PanelProps) {
  return (
    <section>
      <h2>{title}</h2>
      <div>{children}</div>
      {onClose && <button onClick={onClose}>Close</button>}
    </section>
  );
}
